        for y, m in months:
            key = (eid, y, m)
            if key in agg:
                a = agg[key]
                total = a['hours'] * emp_rate[eid] + a['bonus']
            else:
                total = 0.0
            sal = round(total)
            salaries.append(sal)
        result[eid] = salaries

    return result


if __name__ == '__main__':
    import json

    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)
