        reader = csv.DictReader(f)
        for r in reader:
            try:
                tasks[int(r['task_id'])] = float(r['pay_per_completion'])
            except Exception:
                continue

    # Load employees
    emp_rate = {}
    with open('/app/dataset/employees.csv') as f:
        reader = csv.DictReader(f)
        for r in reader:
            try:
                emp_rate[r['PESEL']] = float(r['hourly_rate'])
            except Exception:
