        agg[k]['hours'] += p['hours']
        agg[k]['bonus'] += p['bonus']

    months = sorted(set((y, m) for (_, y, m) in agg.keys()))
    all_emps = sorted(emp_rate.keys())

    result = {}
    for eid in all_emps:
        salaries = []
        for y, m in months:
            key = (eid, y, m)
            if key in agg:
                a = agg[key]
                total = a['hours'] * emp_rate[eid] + a['bonus']
            else:
                total = 0.0
            sal = round(total)
            salaries.append(sal)
        result[eid] = salaries

    return result


